    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;600;700&display=swap" rel="stylesheet">

    <!-- Font Awesome for Icons -->
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">

    <style>
        /* --- CSS STYLES --- */
        /* This would normally be in a separate style.css file */

        /* 1. Global Styles & Variables */
        :root {
            --color-primary: #ffa500; /* CS:GO Orange/Gold */
            --color-secondary: #00aaff; /* A contrasting blue for T/CT feel */
            --color-dark: #121212;
            --color-dark-secondary: #1e1e1e;
            --color-light: #f4f4f4;
            --color-gray: #888;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Poppins', sans-serif;
            background-color: var(--color-dark);
            color: var(--color-light);
            line-height: 1.6;
        }

        a {
            color: var(--color-primary);
            text-decoration: none;
            transition: color 0.3s ease;
        }

        a:hover {
            color: var(--color-light);
        }

        ul {
            list-style: none;
        }

        img {
            max-width: 100%;
            display: block;
        }

        h1, h2, h3 {
            font-weight: 600;
            line-height: 1.2;
            margin-bottom: 1rem;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        /* 2. Header & Navigation */
        .main-header {
            background-color: rgba(30, 30, 30, 0.9);
            padding: 1rem 0;
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            z-index: 1000;
            backdrop-filter: blur(10px);
            border-bottom: 1px solid var(--color-dark-secondary);
        }

        .main-header .container {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            color: var(--color-light);
        }
        .logo span {
            color: var(--color-primary);
        }

        .main-nav ul {
            display: flex;
            gap: 1.5rem;
        }

        .main-nav a {
            color: var(--color-light);
            font-weight: 400;
            padding: 0.5rem 0;
            border-bottom: 2px solid transparent;
        }

        .main-nav a:hover, .main-nav a.active {
            color: var(--color-primary);
            border-bottom-color: var(--color-primary);
        }

        .header-cta .btn {
            margin-left: 1rem;
        }

        /* 3. Utility Classes (Buttons) */
        .btn {
            display: inline-block;
            padding: 0.75rem 1.5rem;
            border-radius: 5px;
            text-transform: uppercase;
            font-weight: 600;
            transition: all 0.3s ease;
        }

        .btn-primary {
            background-color: var(--color-primary);
            color: var(--color-dark);
            border: 2px solid var(--color-primary);
        }

        .btn-primary:hover {
            background-color: transparent;
            color: var(--color-primary);
        }

        .btn-secondary {
            background-color: transparent;
            color: var(--color-light);
            border: 2px solid var(--color-gray);
        }

        .btn-secondary:hover {
            background-color: var(--color-light);
            color: var(--color-dark);
            border-color: var(--color-light);
        }

        /* 4. Hero Section */
        #hero {
            height: 100vh;
            background: url('https://placehold.co/1920x1080/121212/FFA500?text=Epic+CS:GO+Gameplay+Image') no-repeat center center/cover;
            display: flex;
            justify-content: center;
            align-items: center;
            text-align: center;
            position: relative;
        }

        #hero::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.6);
        }

        .hero-content {
            position: relative;
            z-index: 10;
        }

        #hero h1 {
            font-size: 4rem;
            margin-bottom: 0.5rem;
        }

        #hero p {
            font-size: 1.25rem;
            margin-bottom: 2rem;
            max-width: 600px;
        }

        /* 5. Section Base Styles */
        .section {
            padding: 5rem 0;
            background-color: var(--color-dark-secondary);
        }
        .section:nth-child(odd) {
             background-color: var(--color-dark);
        }

        .section-title {
            text-align: center;
            font-size: 2.5rem;
            margin-bottom: 3rem;
        }
        .section-title span {
            color: var(--color-primary);
        }

        /* 6. News Section */
        .news-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .news-card {
            background-color: var(--color-dark);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 0 5px 15px rgba(0,0,0,0.3);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .news-card:hover {
            transform: translateY(-10px);
            box-shadow: 0 10px 25px rgba(255,165,0,0.2);
        }

        .news-card-img {
            height: 200px;
            width: 100%;
            object-fit: cover;
        }

        .news-card-content {
            padding: 1.5rem;
        }

        .news-card-category {
            display: inline-block;
            background: var(--color-primary);
            color: var(--color-dark);
            padding: 0.2rem 0.6rem;
            border-radius: 4px;
            font-size: 0.8rem;
            font-weight: 600;
            margin-bottom: 1rem;
        }

        .news-card h3 {
            font-size: 1.25rem;
        }

        /* 7. Esports Section */
        .esports-highlight {
            display: flex;
            align-items: center;
            gap: 3rem;
            background-color: var(--color-dark);
            padding: 2rem;
            border-radius: 8px;
        }

        .esports-video {
            flex: 2;
        }

        .esports-video iframe {
            width: 100%;
            height: 350px;
            border: none;
            border-radius: 8px;
        }

        .esports-info {
            flex: 1;
        }

        .esports-info h3 {
            color: var(--color-primary);
            font-size: 1.8rem;
        }

        /* 8. Guides Section */
        .guides-grid {
             display: grid;
             grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
             gap: 2rem;
        }

        .guide-card {
            background: var(--color-dark-secondary);
            padding: 2rem;
            text-align: center;
            border-radius: 8px;
            border: 1px solid #333;
            transition: all 0.3s ease;
        }

